# ============================================================
# src/email_report.py
# Originally from Cell 30. Security-fixed: credentials read
# exclusively from environment variables (no hardcoded fallback).
# Extended here to attach chart PNGs generated by charts.py.
# ============================================================
import os
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.image import MIMEImage

from src.config import RESULTS_DIR

CHARTS_DIR = os.path.join(RESULTS_DIR, "charts")

CHART_FILES = [
    "equity_curve.png",
    "drawdown.png",
    "regime_timeline.png",
    "prediction_confidence.png",
    "monthly_returns.png",
    "hit_rate_by_regime.png",
    "ensemble_weights.png",
]


def _build_html_body(prediction: dict, report: dict) -> str:
    sig = prediction.get("signal", "N/A")
    sig_color = {"LONG": "#2ca02c", "SHORT": "#d62728", "NEUTRAL": "#7f7f7f"}.get(sig, "#000")

    rows_pred = "".join(
        f"<tr><td>{k}</td><td><b>{v}</b></td></tr>"
        for k, v in prediction.items()
    )
    rows_report = "".join(
        f"<tr><td>{k}</td><td>{v}</td></tr>"
        for k, v in report.items()
        if k not in ("regime_breakdown", "monthly")
    )

    return f"""
    <html><body style="font-family:Arial,sans-serif;">
      <h2>HSI Daily Prediction — {prediction.get('as_of_date', '')}</h2>
      <p>Signal: <span style="color:{sig_color};font-size:18px;"><b>{sig}</b></span></p>
      <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
        {rows_pred}
      </table>
      <h3>Backtest Snapshot</h3>
      <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">
        {rows_report}
      </table>
      <p style="color:#888;font-size:11px;">
        Automated report — charts attached below.
      </p>
    </body></html>
    """


def send_email(prediction: dict, report: dict) -> None:
    """
    Reads credentials strictly from environment variables:
    EMAIL_SENDER, EMAIL_PASSWORD, EMAIL_RECEIVER (comma-separated).
    No hardcoded fallback — raises if any are missing.
    """
    sender   = os.environ.get("EMAIL_SENDER")
    password = os.environ.get("EMAIL_PASSWORD")
    receiver = os.environ.get("EMAIL_RECEIVER")

    if not all([sender, password, receiver]):
        raise RuntimeError(
            "EMAIL_SENDER / EMAIL_PASSWORD / EMAIL_RECEIVER not set "
            "in environment — configure as GitHub Secrets."
        )

    recipients = [r.strip() for r in receiver.split(",") if r.strip()]

    msg = MIMEMultipart("related")
    msg["Subject"] = f"HSI Prediction — {prediction.get('as_of_date', '')} — {prediction.get('signal', 'N/A')}"
    msg["From"]    = sender
    msg["To"]      = ", ".join(recipients)

    msg.attach(MIMEText(_build_html_body(prediction, report), "html"))

    attached = 0
    for filename in CHART_FILES:
        path = os.path.join(CHARTS_DIR, filename)
        if not os.path.exists(path):
            print(f"  ⚠️  {filename} 不存在，跳過附件")
            continue
        with open(path, "rb") as f:
            img = MIMEImage(f.read())
            img.add_header("Content-Disposition", "attachment", filename=filename)
            msg.attach(img)
            attached += 1

    with smtplib.SMTP("smtp.gmail.com", 587) as server:
        server.starttls()
        server.login(sender, password)
        server.sendmail(sender, recipients, msg.as_string())

    print(f"  ✅ Email 已發送至 {len(recipients)} 位收件人，附帶 {attached} 張圖表")
